import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Days NYC 2023: 100 Years of Sports on Ceph","description":"","frontmatter":{"title":"Ceph Days NYC 2023: 100 Years of Sports on Ceph","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-18T00:00:00.000Z","tags":["Ceph","分布式存储","体育数据存储","高可用性","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_100_Years_of_Sports_on_Ceph.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_100_Years_of_Sports_on_Ceph.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Days_NYC_2023_-_100_Years_of_Sports_on_Ceph.md"};function o(s,a,h,n,_,p){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-基于ceph的体育数据存储项目介绍" tabindex="-1">会议主题：基于Ceph的体育数据存储项目介绍 <a class="header-anchor" href="#会议主题-基于ceph的体育数据存储项目介绍" aria-label="Permalink to &quot;会议主题：基于Ceph的体育数据存储项目介绍&quot;">​</a></h4><h4 id="主讲人-frankie-yank" tabindex="-1">主讲人：Frankie Yank <a class="header-anchor" href="#主讲人-frankie-yank" aria-label="Permalink to &quot;主讲人：Frankie Yank&quot;">​</a></h4><h4 id="会议概要" tabindex="-1">会议概要： <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要：&quot;">​</a></h4><p>本次会议介绍了基于Ceph的体育数据存储项目，旨在处理和存储大量体育视频数据，确保数据的安全、可访问性和长期保存。项目分为多个阶段，第一阶段计划构建40PB的Active Archive，并采用Ceph作为核心存储技术。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h4><ol><li><p><strong>项目背景与动机</strong>：</p><ul><li>项目源于对大量体育视频数据的存储需求，目前这些数据存储在磁带上，数据量不断增长。</li><li>数据具有不可替代性，对历史和文化具有重要意义，因此需要确保数据的长期保存和可用性。</li><li>除了保存数据，还需要能够对数据进行计算分析和商业化利用。</li></ul></li><li><p><strong>技术选型与基础设施需求</strong>：</p><ul><li>选择Ceph作为存储解决方案，因其开源、社区支持强大、可扩展性强。</li><li>需要构建一个不仅适用于当前，还能适应未来数据增长和类型变化的存储基础设施。</li><li>基础设施需具备高可用性、快速访问、多站点可访问性，并避免供应商锁定。</li></ul></li><li><p><strong>项目实施细节</strong>：</p><ul><li>项目分为多个阶段，第一阶段计划构建40PB的Active Archive。</li><li>基础设施包括两个位于美国东西海岸的站点，每个站点配备多个生产集群和沙箱环境。</li><li>沙箱环境用于测试和验证新功能、升级和配置变更，确保生产环境的稳定性和可靠性。</li></ul></li><li><p><strong>性能与经济性分析</strong>：</p><ul><li>通过详细的规划和系统工程设计，确保了基础设施的高性能和低成本。</li><li>通过与公共云成本的比较，展示了项目在经济上的优势。</li></ul></li><li><p><strong>面临的挑战与解决方案</strong>：</p><ul><li>项目实施过程中遇到的挑战包括硬件选择、网络设计、软件集成和自动化。</li><li>通过使用Ceph Ansible等工具和自定义逻辑，解决了数据一致性、性能调优和故障恢复等问题。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ul><li>确定了使用Ceph作为核心存储技术，并构建了相应的存储基础设施。</li><li>设立了沙箱环境用于测试和验证，确保生产环境的高可用性和可靠性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续扩展和优化存储基础设施，以适应未来数据的增长和变化。</li><li>持续进行性能调优和故障恢复测试，确保系统的长期稳定运行。</li><li>探索更多商业化利用数据的可能性，以实现数据的最大价值。</li></ul><h4 id="结论" tabindex="-1">结论： <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论：&quot;">​</a></h4><p>本次会议详细介绍了基于Ceph的体育数据存储项目的背景、实施细节和面临的挑战，展示了项目在技术选型、经济性和可靠性方面的优势，并明确了后续的行动计划。</p>',13)])])}const c=e(r,[["render",o]]);export{u as __pageData,c as default};
